mapper.sql:
SELECT d.id, d.school_id, d.delivery_no, d.order_no, COALESCE(o.school_name, smsg.school_name) AS school_name, COALESCE(o.supplier_name, sm.supplier_name, sr.supplier_name) AS supplier_name, d.delivery_status, COALESCE(SUM(COALESCE(i.delivery_num, 0)), 0) AS delivery_total_num, COALESCE(SUM(COALESCE(i.sign_num, 0)), 0) AS sign_total_num, d.carriage_fee, d.delivery_time, d.sign_time FROM xfpt_delivery_order d LEFT JOIN xfpt_order_info o ON o.id = d.order_id AND o.del_flag = 0 LEFT JOIN xfpt_school_message smsg ON smsg.id = d.school_id LEFT JOIN xfpt_supplier_message sm ON sm.id = d.supplier_id AND sm.del_flag = 0 LEFT JOIN xfpt_school_supplier_rel sr ON sr.school_id = d.school_id AND sr.supplier_id = d.supplier_id AND sr.cooperate_status = '1' AND sr.del_flag = 0 LEFT JOIN xfpt_delivery_order_item i ON i.delivery_id = d.id AND i.del_flag = 0
d.del_flag = 0 AND d.school_id = #{schoolId}
AND sr.id IS NOT NULL
AND d.delivery_no LIKE concat('%', #{deliveryNo}, '%') AND d.order_no LIKE concat('%', #{orderNo}, '%') AND COALESCE(o.school_name, smsg.school_name) LIKE concat('%', #{schoolName}, '%') AND COALESCE(o.supplier_name, sm.supplier_name, sr.supplier_name) LIKE concat('%', #{supplierName}, '%') AND d.delivery_status = #{deliveryStatus}
AND DATE_FORMAT(d.delivery_time, '%Y-%m-%d') >= #{params.beginTime}
AND DATE_FORMAT(d.delivery_time, '%Y-%m-%d') <= #{params.endTime}
GROUP BY d.id, d.school_id, d.delivery_no, d.order_no, COALESCE(o.school_name, smsg.school_name), COALESCE(o.supplier_name, sm.supplier_name, sr.supplier_name), d.delivery_status, d.carriage_fee, d.delivery_time, d.sign_time ORDER BY d.delivery_time DESC, d.id DESC
